data_market_history_fetch_service_abort_v1<-function(code){if(!is.character(code)||length(code)!=1L||!grepl("^(data|desktop)_market_history_fetch_[a-z_]+$",code))code<-"data_market_history_fetch_boundary_failed";stop(structure(list(message=code,call=NULL,code=code),class=c("spot_data_market_history_fetch_error_v1","error","condition")))}
new_data_market_history_fetch_service_v1<-function(project_root,context){
 if(!is.character(project_root)||length(project_root)!=1L||!dir.exists(project_root)||!isTRUE(tryCatch(runtime_context_valid(context),error=function(error)FALSE))||!identical(context$runtime_mode,"desktop_product")||!identical(context$role,"desktop_owner"))data_market_history_fetch_service_abort_v1("data_market_history_fetch_service_invalid")
 project_root<-normalizePath(project_root,winslash="/",mustWork=TRUE);python<-Sys.which("python3");cli<-file.path(project_root,"scripts","desktop_market_history_fetch.py");data_space<-runtime_data_space_path(context);if(!nzchar(python)||!file.exists(cli)||!dir.exists(data_space)||nzchar(Sys.readlink(cli))||nzchar(Sys.readlink(data_space)))data_market_history_fetch_service_abort_v1("data_market_history_fetch_service_invalid")
 previews<-new.env(hash=TRUE,parent=emptyenv());context_payload<-list(tenant_id=context$tenant_id,user_id=context$user_id,data_space_id=context$data_space_id,actor_id="market_worker",role="market_worker")
 run_cli<-function(command,payload){encoded<-as.character(jsonlite::toJSON(payload,auto_unbox=TRUE,null="null",digits=NA));output<-tryCatch(suppressWarnings(system2(python,c("-B","-E","-s",shQuote(cli),shQuote(command)),stdout=TRUE,stderr=TRUE,input=encoded)),error=function(error)structure(character(),status=1L));status<-attr(output,"status");if(is.null(status))status<-0L;parsed<-tryCatch(jsonlite::fromJSON(tail(output,1L),simplifyVector=FALSE),error=function(error)NULL);if(is.null(parsed)||as.integer(status)!=0L||isTRUE(parsed$status%in%c("blocked","failed")))data_market_history_fetch_service_abort_v1(if(is.null(parsed$code))"data_market_history_fetch_boundary_failed"else parsed$code);parsed}
 preview<-function(listing_ref,mapping,start_date,end_date,mode,created_at_utc){result<-run_cli("preview",list(context=context_payload,data_space_path=data_space,listing_ref=listing_ref,mapping=mapping,required_start_date=start_date,as_of_date=end_date,mode=mode,created_at_utc=created_at_utc));trusted<-result$trusted_preview;public<-result$public_preview;if(!is.list(trusted)||!is.list(public))data_market_history_fetch_service_abort_v1("data_market_history_fetch_boundary_failed");ref<-paste0("fetchp_",substr(digest::digest(as.character(jsonlite::toJSON(trusted,auto_unbox=TRUE,null="null",digits=NA)),algo="sha256",serialize=FALSE),1L,32L));public$preview_ref<-ref;assign(ref,list(consumed=FALSE,public=public,trusted=trusted),envir=previews);public}
 execute<-function(public_preview,confirmed){if(!is.list(public_preview)||!is.character(public_preview$preview_ref)||length(public_preview$preview_ref)!=1L||!exists(public_preview$preview_ref,envir=previews,inherits=FALSE))data_market_history_fetch_service_abort_v1("data_market_history_fetch_preview_required");stored<-get(public_preview$preview_ref,envir=previews,inherits=FALSE);if(isTRUE(stored$consumed))data_market_history_fetch_service_abort_v1("data_market_history_fetch_attempt_consumed");if(!identical(stored$public,public_preview))data_market_history_fetch_service_abort_v1("data_market_history_fetch_preview_required");if(isTRUE(stored$public$confirmation_required)&&!isTRUE(confirmed))data_market_history_fetch_service_abort_v1("data_market_history_fetch_confirmation_required");stored$consumed<-TRUE;assign(public_preview$preview_ref,stored,envir=previews);python_public<-stored$public;python_public$preview_ref<-NULL;result<-run_cli("apply",list(context=context_payload,data_space_path=data_space,trusted_preview=stored$trusted,public_preview=python_public,confirmed=isTRUE(confirmed)));c(list(),result$public_result)}
 structure(list(contract_version="data_market_history_fetch_service_v1",preview=preview,execute=execute,automatic_provider_access=FALSE,automatic_retry=FALSE,browser_paths_exposed=FALSE,browser_context_exposed=FALSE),class=c("spot_data_market_history_fetch_service_v1","list"))
}
